package com.hbm.inventory.fluid.trait;

import com.hbm.handler.pollution.PollutionHandler;
import com.hbm.handler.pollution.PollutionHandler.PollutionType;
import com.hbm.inventory.fluid.FluidType;
import com.hbm.inventory.fluid.trait.FluidTrait.FluidReleaseType;
import net.minecraft.core.BlockPos;

import java.util.EnumMap;
import java.util.Map;

/**
 * Goal19A release traits over the production FT_Polluting and FluidTrait.onRelease in the Goal19A barrel world, and the FLUE
 * polluting chain parsed from the production Fluids.java row (Goal19AFlue is generated by verify_goal19a_pollution.py).
 * Original d31426c: FT_Polluting.java:56-59 (SPILL: releaseMap value * overflowAmount, BURN: burnMap value * overflowAmount);
 * Fluids.java:416 (FLUE burn SOOT_GAS, release SOOT_GAS * 5).
 */
public class Goal19APollutionTraits {
    static int checks, scenarios;
    static void check(boolean condition, String message) { if(!condition) throw new AssertionError(message); checks++; }

    /** Original Fluids.java SOOT_GAS = SOOT_PER_SECOND * 0.005F with SOOT_PER_SECOND = 1F / 25F. */
    static final float ORIGINAL_SOOT_GAS = 1F / 25F * 0.005F;

    static Map<PollutionType, Float> recorded() {
        Map<PollutionType, Float> out = new EnumMap<>(PollutionType.class);
        for(PollutionHandler.Event e : PollutionHandler.events) {
            if(out.containsKey(e.type())) throw new AssertionError("more than one increment for " + e.type());
            out.put(e.type(), e.amount());
        }
        return out;
    }

    static Map<PollutionType, Float> scaled(Map<PollutionType, Float> map, int mB) {
        Map<PollutionType, Float> out = new EnumMap<>(PollutionType.class);
        for(Map.Entry<PollutionType, Float> entry : map.entrySet()) out.put(entry.getKey(), entry.getValue() * mB);
        return out;
    }

    public static void main(String[] args) {
        FT_Polluting flue = Goal19AFlue.flue();
        check(flue.burnMap.equals(Map.of(PollutionType.SOOT, ORIGINAL_SOOT_GAS)), "FLUE burn map SOOT = SOOT_GAS " + flue.burnMap);
        check(flue.releaseMap.equals(Map.of(PollutionType.SOOT, ORIGINAL_SOOT_GAS * 5)), "FLUE spill map SOOT = SOOT_GAS * 5, not * 25 " + flue.releaseMap);

        FT_Polluting synthetic = new FT_Polluting().release(PollutionType.POISON, .0123F).release(PollutionType.SOOT, .5F).burn(PollutionType.HEAVYMETAL, .25F).burn(PollutionType.SOOT, .07F);
        BlockPos pos = new BlockPos(1, 2, 3);
        for(FT_Polluting trait : new FT_Polluting[] {synthetic, flue}) {
            String name = trait == flue ? "FLUE" : "synthetic";
            for(int mB : new int[] {1, 7, 250}) {
                for(FluidReleaseType type : FluidReleaseType.values()) {
                    Map<PollutionType, Float> expected = type == FluidReleaseType.VOID ? Map.of() : scaled(type == FluidReleaseType.SPILL ? trait.releaseMap : trait.burnMap, mB);
                    scenarios++;
                    PollutionHandler.reset();
                    trait.onFluidRelease(null, pos, null, mB, type);
                    check(recorded().equals(expected), name + " onFluidRelease " + type + " x" + mB + "mB: map value * overflowAmount " + expected + " (got " + recorded() + ")");
                    scenarios++;
                    PollutionHandler.reset();
                    FluidType fluid = new FluidType("GOAL19A_" + name + "_" + type + "_" + mB, 9000 + mB, false, false);
                    fluid.addTraits(trait);
                    FluidTrait.onRelease(null, pos, fluid, null, type, mB);
                    check(recorded().equals(expected), name + " FluidTrait.onRelease " + type + " x" + mB + "mB reaches the scaled release " + expected + " (got " + recorded() + ")");
                }
            }
        }
        System.out.println("Goal19A release traits: " + checks + " assertions; " + scenarios + " independent scenarios; 0 executed ticks");
    }
}
